$stmt = db()->prepare("SELECT id, invoice_token, created_at, total_amount FROM orders WHERE customer_id = ? AND status <> 'Annulée' ORDER BY created_at DESC"); $stmt->execute([currentCustomer()['id']]); $orders = $stmt->fetchAll();
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mes factures | Woodin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><a href="mon-compte.php">Mon compte</a><h1>Mes factures</h1><div class="table-responsive mt-4"><table class="table bg-white"><thead><tr><th>Facture</th><th>Date</th><th>Commande</th><th>Montant</th><th>Téléchargement</th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td>Facture #<?= (int)$order['id'] ?></td><td><?= e($order['created_at']) ?></td><td>#<?= (int)$order['id'] ?></td><td><?= number_format($order['total_amount'],0,',',' ') ?> FCFA</td><td><a class="btn btn-sm btn-warning" href="download-invoice.php?id=<?= (int)$order['id'] ?>" download>PDF</a></td></tr><?php endforeach; ?><?php if (!$orders): ?><tr><td colspan="5">Aucune facture disponible.</td></tr><?php endif; ?></tbody></table></div></main></body></html>
